def confusion_counts(y_true, y_pred):
    tp = fp = fn = tn = 0
    for a, p in zip(y_true, y_pred):
        if a == 1 and p == 1:
            tp += 1
        elif a == 0 and p == 1:
            fp += 1
        elif a == 1 and p == 0:
            fn += 1
        else:
            tn += 1
    return [tp, fp, fn, tn]
